from nlib import *
S=[]
S.append(N("blood_vessels","Blood vessels","structure","anatomy",1.0,"The network of arteries, veins and capillaries that carries blood everywhere.","Blood vessels are the body's plumbing: arteries carry blood out, capillaries exchange materials, and veins bring blood back.","Arteries have thick muscular walls, veins have valves and thin walls, and capillaries are one cell thick.","Total resistance is set mainly by arterioles; vessel tone is regulated by endothelial NO, sympathetic nerves, and angiotensin II; angiogenesis is driven by VEGF.",[("Total length","≈ 100,000 km (often quoted)"),("Capillaries","≈ 10^10")],"If all your capillaries were laid end to end they would circle Earth more than once by the usual estimate, though that figure is approximate.",par=["cardiovascular_system"],made=["smooth_muscle_tissue","epithelial_tissue","dense_connective_tissue"],refs=[("ANP","20.1")],kn=("blood_circulation",),cert="C2"))
S.append(N("synapse","Synapse","structure","micro",2e-8,"The tiny junction where one neuron signals to the next.","A synapse is a microscopic gap across which chemical messengers pass.","The gap (cleft) is about 20 nanometers wide; vesicles on one side release neurotransmitter onto receptors on the other.","Active zone with Ca2+ channels and docked vesicles; postsynaptic density with scaffold PSD-95; AMPA/NMDA receptor trafficking underlies LTP; ≈ 10^14-10^15 synapses in the human brain.",[("Cleft","≈ 20 nm"),("Synapses in brain","≈ 10^14-10^15")],"The brain's synapse count is in the hundreds of trillions.",par=["nervous_system"],made=["neuron"],proc=["synaptic_transmission"],refs=[("ANP","12.5")],kn=("synapse_plasticity",),mol=["acetylcholine","dopamine","gaba"]))
S.append(N("neuromuscular_junction","Neuromuscular junction","structure","micro",5e-5,"The synapse where a motor neuron commands a muscle fiber.","This is where nerve meets muscle, using the chemical acetylcholine.","One motor neuron's terminal releases acetylcholine onto receptors on the muscle fiber.","Nicotinic ACh receptors (≈ 10^4 µm⁻²) produce end-plate potentials, with a high safety factor; acetylcholinesterase ends the signal; targeted by curare and botulinum toxin.",[("Safety factor","≈ 3-5×"),("Cleft","≈ 50 nm")],"Botulinum toxin paralyzes muscle by blocking acetylcholine release here.",par=["muscular_system"],made=["neuron","skeletal_muscle_fiber"],proc=["muscle_contraction"],refs=[("ANP","10.3")],kn=("muscle_contraction",),mol=["acetylcholine"]))
S.append(N("tendon","Tendon","structure","anatomy",0.2,"A tough cord of collagen joining muscle to bone.","Tendons transmit the pull of muscles to bones.","They are strong but poorly supplied with blood, so heal slowly.","Parallel type I collagen with tenocytes; stores elastic energy (Achilles ≈ 35% of running work); tensile strength ≈ 50-100 MPa.",[("Strength","≈ 50-100 MPa")],"The Achilles tendon can handle loads of several times body weight.",par=["muscular_system"],made=["dense_connective_tissue"],refs=[("ANP","11.1")],kn=("musculoskeletal",)))
save("body_extra",S)
